                        //#endregion
                        // zaregistruji si "change" na políčka s novými hodnotami, která nemají "change:"            
                        this.findFields(".js-change-sentry").gfield("option", "change", (ev, changeObj) => {
                            this.setOkButton();
                        });
                        if (this.cvDebug)
                            this.log.trace("GDlgZmena(onContentReady) - FORM vytvořen");
                        //#region  dlg_MajZmena.init( )
                        // inicializace režimu práce s položkama karty
                        // TODO: df_drh_id._setModeEdit( ng_modeEditDok )
                        // select karty - PSvoboda: provedeno na předchozím contentu
                        // provedeno v CS anebo na předchozím contentu ??
                        // v případě odpisu select odpisových hodnot
                        if (this.majpol.maj.priz_odp === 10)
                            this.mode_odp_drh = 10;
                        // provedeno v CS
                        // Call MajInit._getModeOdpSkm( majpol_p.maj.skupina_id )
                        //  inicializace příznaku odpisu            
                        this.mode_odp_krt = this.majpol.maj.priz_odp;
                        this.changeTopMmb = false;
                        //#endregion
                        //#region  dlg_MajZmenaTop.init( ) - pouze kód, který již není v předchozím init( )
