                        if (this.cvDebug)
                            this.log.trace("--- MODEL --- DTO aplikováno");
                        //  inicializace topologických polí kvůli speciálnímu řízení přístupu - MMB
                        if (this.MAJ_RAD_TOPMMB && this.cvMajInitRezimEVS)
                            this.setStredisko(this.majpol.maj.stredisko);
                        // TODO:  předplnění nových hodnot údaji z rozhraní
