                                            //#region tblPol.wmKDInvCisNewCard( ) 
                                            //--------------
                                            $(ev.target).findFields("skupina_zkr").gfield("model", "apply", { skupina_id: 0, s_unique: 1 }); // nechci spustit KO předkontací, pouze předplnit SKM
                                            this.nTblPolZev = WebClient.nZevUnik; // mat_cis.matcis._putZev( ng_zevUnik )
