                    builder.removeDefinition("menuTisk", GDbd.DefinitionKind.MenuBar);
                    builder.removeDefinition("menuTiskHistorie", GDbd.DefinitionKind.MenuBar);
                    builder.removeDefinition("menuTiskUzivatelskePoznamky", GDbd.DefinitionKind.MenuBar);
