                saveRegTzh() {
                    this.logFunctionCall("tblPol.saveRegTzh");
                    // KO
                    if (!this.nTblPolTypDM) {
                        this.dialogs.error("Nebyl zjištěn typ DM!");
                        return $.Deferred().reject();
                    } // end if
                    this.logWatch("nTblPolTypDM", this.nTblPolTypDM);
                    if (this.cvCMinDHM == null || this.cvCMinDHM == undefined) {
                        this.dialogs.error("Chyba konfigurace modulu - není nastavena minimální povinná hranice odpisu DHM!");
                        return $.Deferred().reject();
                    } // end if
                    this.logWatch("cvCMinDHM", this.cvCMinDHM);
                    if (this.cvCMinDNM == null || this.cvCMinDNM == undefined) {
                        this.dialogs.error("Chyba konfigurace modulu - není nastavena minimální povinná hranice odpisu DNM!");
                        return $.Deferred().reject();
                    } // end if
                    this.logWatch("cvCMinDNM", this.cvCMinDNM);
                    return this.setZmenaCenyOdp().then(() => {
                        var Msg = 'jres:24534763'; //RC 24534763 : Požadovaná částka převyšuje minimální nutnou hranici pro provedení technického zhodnocení. Opravdu požadujete provést pouze záznam do registru technického zhodnocení?
                        // KO ceny vůči hranici dle typu DM
                        if (this.nTblPolTypDM === 10 && this.cvCMinDNM <= this.majpol.pol.c) {
                            return this.dialogs.confirm("jres:24534075", Msg).createDialogPromise("yes").then(() => {
                                return this.createNewPol();
                            });
                        } //endif
                        else if (this.nTblPolTypDM === 20 && this.cvCMinDHM <= this.majpol.pol.c) {
                            return this.dialogs.confirm("jres:24534075", Msg).createDialogPromise("yes").then(() => {
                                return this.createNewPol();
                            });
                        } //endif
                        else
                            return this.createNewPol();
                    }); // end setZmenaCenyOdp().then()
                } // end function (saveRegTzh)
                saveTzh() {
                    this.logFunctionCall("tblPol.saveTzh");
                    if (this.cvNormalDok) {
                        // definice změny PC a vstupních hodnot
                        return this.setZmenaCenyOdp().then(() => {
                            // zjištění a případné zahrnutí položek z registru žurnálu
                            return this.setPolRegTzh(0, this.majpol.maj.inv_cis) // ng_modetzhKrtDok = 0
                                .then(() => {
                                return this.createNewPol();
                            }); // end setPolRegTzh().then()
                        }); // end setZmenaCenyOdp().then()
                    }
                    else
                        return this.createNewPol();
                } // end function (saveTzh)
