                //======================================================================================
                getFields() {
                    this.logFunctionCall("GMajDokladDetail.getFields()");
                    this.findForms("FormHeader").findFields("df_ac, df_ac_ag, df_typ_dok, df_popis").gfield("model", "collect", this.DetailDto);
                    //this.findForms("FormDoklad").findFields(
                    //    "df_kod_poh, df_dat_uup, df_dat_zdan, " +
                    //    // "df_dat_termin" asi mohu sebrat vždy, neb při změně typ_dok se případně resetuje v InitHdr dokladu
                    //    "df_ico_ext, df_nks_ext, df_dat_termin, df_ixs_ref, " +
                    //    "df_mena, df_kurz, " +
                    //    "df_id_top, " + // seberu vždy(!) id_top - pro EVS musí být nastaveno a pro NKS případně doplním z EkoParams
                    //    "df_esu_txt, df_ac_ext, df_dat_ext, df_ps_fak, " +
                    //    // TODO: majpid.ixp_prim = df_ps_fak._getIxpPrim(  )
                    //    // TODO: majpid.typ_ag_prim = df_ps_fak._getTypAgPrim( )
                    //    // TODO: sebrat "df_c_c" a "df_c_c_dph" a "df_pocet_pol" ??
                    //    "df_c_c_zmena," +
                    //    "df_naklad_1, df_naklad_2, df_naklad_3"
                    //)
                    this.findForms("FormDoklad").findFields()
                        .gfield("model", "collect", this.DetailDto);
                    // sběr z druhého formu - typ_dok: LV
                    if (this.DetailDto.typ_dok === WebClient.nTypDokVLikv || this.DetailDto.typ_dok === WebClient.nTypDokRegTzhNm2Na)
                        this.findForms("FormSpotreba").findFields("df_stredisko, df_ixs_orj_nak, df_objekt, df_ixs_ref_nak, df_trida, df_ext_1, df_ext_2, df_ext_3").gfield("model", "collect", this.DetailDto);
                    // interní RES a interní vratka
                    if (this.DetailDto.typ_dok === WebClient.nTypDokResZapI || this.DetailDto.typ_dok === WebClient.nTypDokResRetI) {
                        // přenesu vybraného referenta do IXS_ESU_EXT
                        if (this.DetailDto.ixs_ref_int && this.DetailDto.ixs_ref_int != '0000SR00000B') {
                            // REF do ESU
                            this.DetailDto.ixs_esu_ext = this.DetailDto.ixs_ref_int;
                            // vynuluju NS_EXT
                            this.DetailDto.nks_ext = "";
                        } // endif
                    } // endif (ResZapI a ResRetI)
                    //VLA:Detail - save - sběr dat z Popisných a rozšiřujících vlastností
                    this.DetailDto.vlastnosti = Gordic.PopisneVlastnosti.collectValues(this);
                } // end function ( getField ) ------------------------------------------------------
                //======================================================================================
                // změna celkové ceny dokladu
                changeDokC() {
                    this.logFunctionCall("changeDokC");
                    this.oProdPrirazky = null;
                    var def = $.Deferred();
                    if (this.cvEnblLocRwEvid && this.DetailDto.ixp && this.DetailDto.pocet_pol > 0
                        &&
                            this.DetailDto.mp_stav > WebClient.nSDNavrh && this.DetailDto.mp_stav < WebClient.nSDProuctovano
                        &&
                            this.DetailDto.uct_stav < WebClient.nSDProuctovano) {
                        // pro doklady typu P a povoleném parametru
                        if ((this.DetailDto.typ_dok === WebClient.nTypDokP) && this.MAJ_DOK_PRIMCC) { // || this.DetailDto.typ_dok === nTypDokPNKS
                            return Maj.WebClient.Dialogs.GDlgZmenaCenyDokladu.showDlg({
                                related: this.element,
                                data: {
                                    c_c: this.DetailDto.c_c,
                                    c_dph_n: this.DetailDto.c_dph_n,
                                    c_dph_s: this.DetailDto.c_dph_s,
                                    c_dph_3: this.DetailDto.c_dph_3,
                                    c_dph_4: this.DetailDto.c_dph_4,
                                    c_c_dph: this.DetailDto.c_c_dph,
                                    changed: false
                                },
                                ac: this.DetailDto.ac,
                                ctx: {
                                    ekoDphSnText: this.cvEkoDphS1Text,
                                    ekoDph2SnText: this.cvEkoDphS2Text,
                                    ekoDph2SnPriz: this.cvEkoDphS2Used,
                                    ekoPlatceDph: this.cvEkoDphPlatce !== 0,
                                },
                            })
                                .then((returnValue) => {
                                if (returnValue) {
                                    // upravím ceny v DetailDto
                                    if (returnValue.changed) {
                                        this.DetailDto.c_c = returnValue.c_c;
                                        this.DetailDto.c_dph_n = returnValue.c_dph_n;
                                        this.DetailDto.c_dph_s = returnValue.c_dph_s;
                                        this.DetailDto.c_dph_3 = returnValue.c_dph_3;
                                        this.DetailDto.c_dph_4 = returnValue.c_dph_4;
                                        this.DetailDto.c_c_dph = returnValue.c_c_dph;
                                    } // endif
                                    return def.resolve(returnValue.changed); // OK, pokračujeme schválením s novými cenami
                                }
                                else {
                                    // PSvoboda: zjednodušení
                                    return def.reject(); // dal zrušit, tak zrušit...
                                    //return this.dialogs.confirm(
                                    //    "jres:24534075", //RC 24534075 : Dotaz
                                    //    "Požadujete provést schválení dokladu?"  //RC 24534713 : Máte neuložené změny, chcete opravdu odejít bez uložení změn?
                                    //).createDialogPromise("yes");
                                }
                            });
                        }
                        // obsluha prodejní přirážky
                        // pro doklady typu V + kategorii dokladu Prodej + při zapnutém parametru (enable.prirazka)
                        else if (this.cvEnblPrirazka) {
                            // SalModalDialog( dlg_MajProdPri, hWndForm, ng_selmodeYes,  ng_typshowCisPriSel, majpid.ixp, prirazka )                     
                            return this.dialogs.showModalWindow(WebClient.Dialogs.GProdejniPrirazky, {
                                prizVyberPri: 1, // výběr - ng_typshowCisPriSel
                                ixp: this.DetailDto.ixp,
                                prizJenAktivni: 1, // aktivní položky číselníku - ng_selmodeYes
                            }, {
                                width: 600, height: 600,
                            }).createDialogPromise().then((returnValue) => {
                                if (returnValue && returnValue.length > 0) { // pole klíčů MAJSDPR.prirazka
                                    // this.dialogs.alert("TEST, počet=" + returnValue.length);
                                    this.oProdPrirazky = returnValue;
                                    return def.resolve(true); // bude se měnit cena
                                }
                                else
                                    return $.Deferred().reject().promise();
                            });
                        }
                        else
                            def.resolve(false); // OK - ale nemění se cena
                    } // endif
                    else
                        def.resolve(false); // OK - cenu ale nelze měnit
                    return def.promise();
                } // end function ( changeDokC ) 
