                                        //} // end if (debug)
                                        // set hodnoty do políčka (buď celé UEAB_XXX nebo jen část UEA)
                                        opts.getForm("FormCeny").findFields("df_ueab_evi").gfield("setValue", { drh_id: opts.DetailDto.drh_id, dev: opts.DetailDto.dev, uea: opts.ucty.uea_evi, ixs_vue: opts.cvIxsVue, ueab_xxx: data });
                                        // pokud je pole naplněno, je to OK - jinak shodím požadavek v recordu
                                        if (rezim === 1 && data !== l_ueab_evi)
                                            opts.DetailDto.ueab_evi = data;
