                spoctiDatZdan(mesobd_odp, step) {
                    let rok = this.cvEkoRok;
                    let mes = mesobd_odp + step; //
                    let den = this.getMaxDayInMonth(mes, rok);
                    let datZdan = new Date(rok, mes - 1, den); //new Date(rok, mes, den, 0, 0, 0);
                    return datZdan;
                } // end method (spoctiDatZdan)
                getMaxDayInMonth(mes, rok) {
                    if (mes === 1 || mes === 3 || mes === 5 || mes === 7 || mes === 8 || mes === 10 || mes === 12)
                        return 31;
                    if (mes === 2) { // únor - počítám přestupný rok
                        if (rok % 4 === 0) { // přestupný rok
                            // je-li dělitelný 100, ale ne 400, pak není přestupný!
                            if (rok % 100 === 0 && rok % 400 !== 0)
                                return 28;
                            else
                                return 29;
                        } // end if
                        else
                            return 28;
                    }
                    else
                        return 30; // ostatní měsíce
                } // end method (spoctiDatZdan)
                kontrolaOdpisu(odpDefs) {
                    const that = this;
                    this.beginOperation("Probíhá kontrola před odpisem...");
                    //this.provedeniOdpisu(odpDefs); //kvuli vyvoji
                    //!pro ostrý odpis potřebuju pohyb, jinak mi stačí DEV
                    //525.21 19.12.24 kontrola definice elementů
                    let promise = that.isl.MajOdpis.checkDefPoh({ odpisStartData: that.odpisStartDto }).get();
                    if (that.odpisStartDto.zpusob !== 3)
                        promise = $.Deferred().resolve(true);
                    //promise =
                    //if (that.odpisStartDto.zpusob === 3)
                    //    that.isl.MajOdpis.checkDefPoh({ odpisStartData: that.odpisStartDto }).get().done((result) => {
                    //        //if (result == false) {
                    //        //    that.showFlash("Není definován pohyb pro všechny druhy evidence odepisovaného majetku", "error", "#IDneniPohyb");
                    //        //}
                    //        return result;
                    //    })
                    //else
                    promise.promise()
                        .then((result) => {
                        if (result)
                            return this.call("ZkontrolovatOdpis", {
                                odpDefs: odpDefs
                            });
                        else {
                            //return $.Deferred().resolve().promise();
                            return $.Deferred().reject("Není definován pohyb pro všechny druhy evidence odepisovaného majetku").promise();
                        }
                    })
                        .then((koResult) => {
                        this.endOperation();
                        if (koResult.errLevel === 0)
                            this.provedeniOdpisu(odpDefs);
                        // OK s upozorněním
                        else if (koResult.errLevel === 1)
                            this.dialogs.warning("Upozornění", koResult.userText).on("close", () => {
                                this.provedeniOdpisu(odpDefs);
                            });
                        // OK s potvrzením od uživatele
                        else if (koResult.errLevel === 2)
                            this.dialogs.confirm("jres:24534074", koResult.userText).on("close", (ev, retVal) => {
                                if (retVal === "yes")
                                    this.provedeniOdpisu(odpDefs);
                            });
                        else
                            this.dialogs.error(koResult.userText ?? "Chyba při kontrole odpisu");
                    }, 
                    //fail                    
                    (error) => {
                        this.dialogs.error(error ?? "Chyba při kontrole odpisu");
                        //that.showFlash(error, "error", "#IDneniPohyb");
                    }) // end then
                        .always(() => {
                        this.endOperation();
                    });
                } // end method (kontrolaOdpisu)
                provedeniOdpisu(odpDefs) {
                    var l_bAsynchronne = true;
                    if (l_bAsynchronne) {
                        //if (odpDefs.zpusob! < 3)
                        Gordic.Async.GTaskManager.start("Gordic.Maj.Server.GMajOdpisAsync", odpDefs);
                    }
                    //po staru
                    else {
                        this.beginOperation("Probíhá odpis dlouhodobého majetku...");
                        this.call("ProvestOdpis", {
                            odpDefs: odpDefs
                        })
                            .then((ikc) => {
                            //this.endOperation();
                            // uložím si metadata provdeného odpisu
                            this.lastOdpDefs = odpDefs;
                            // nápověda pro akci "Protokol"
                            let toolTipText = "Protokol posledního zkušebního odpisu ";
                            if (odpDefs.zpusob == 2)
                                toolTipText = "Protokol posledního plánu odpisu ";
                            if (odpDefs.zpusob == 3)
                                toolTipText = "Protokol posledního ostrého odpisu ";
                            this.lastProtocolActionTt = toolTipText;
                            // zpřístupním protokol                    
                            this.actions?.actProtokol?.enabled(true);
                            this.actions?.actProtokol?.update({ tooltip: toolTipText });
                            //this.dialogs.alert("Odpis byl dokončen");
                            if (odpDefs.zpusob === 3) {
                                //this.actions?.actHistorie?.run(); // přehled ostrých odpisů
                                //this.refreshData().then(() => {
                                this.showTmpProtocol(odpDefs); // ukážu protokol
                                //}) // end then 
                            }
                            else {
                                // zapíši si IKC
                                WebClient.nLastOdpProtocolIkc = ikc;
                                this.arrUsedIkcs.push(ikc);
                                this.showTmpProtocol(odpDefs); // dočasný protokol
                            } // end if-else
                        }) // end then
                            .always(() => {
                            this.endOperation();
                        });
                    }
                } // end method (provedeniOdpisu)
                showTmpProtocol(odpDefs) {
                    let mesObdOdp = parseDate(odpDefs.dat_zdan).getMonth() + 1;
                    let rokObdOdp = parseDate(odpDefs.dat_zdan).getFullYear();
                    let sObdOdp = mesObdOdp.toString() + "/" + rokObdOdp;
                    // SalModalDialog( dlg_MajOdp, hWndForm, zpusob_odp, druh_odp_p, '', '', druh_odp_p, SalDateYear(majpid.dat_zdan), SalDateMonth(majpid.dat_zdan), df_rok_obd_plan, 0, majpid.dev  )
                    this.navigate('Gordic.Maj.WebClient.GProtokolOdpisu', {
                        argRezim: odpDefs.zpusob, // 1 - zkušební, 2 = plán, 3 - ostrý
                        argDruhOdp: this.odpisStartDto.druh_odp,
                        argObdobiOdp: sObdOdp,
                        IxpOdp: null,
                        argPlanDo: odpDefs.plan_do,
                        argIkc: WebClient.nLastOdpProtocolIkc
                    });
                } // end method (showTmpProtocol)
