                //----------------------       
                gfGetTypKla(typKla) {
                    if (typKla === 0)
                        return "SKP"; // ng_typklaSKP
                    if (typKla === 1)
                        return "CZ-CC"; // ng_typklaCZCC
                    if (typKla === 2)
                        return "KPOZ"; // ng_typklaKPOZ
                    if (typKla === 3)
                        return "CZ-CPA"; // ng_typklaCZCPA
                    this.dialogs.error("Neznámý typ klasifikace pro funkci 'gfGetTypKla'.");
                    return "???";
                }
                validateRokOdpisov(myVal, bUcetni) {
                    this.logFunctionCall("validateRokOdpisov");
                    // KO validátoru
                    if (bUcetni)
                        this.dialogs.error("Funkce validateRokOdpisov() není pro prvek Ú odpisu realizována");
                    this.findForms("FormOdpD").findFields("df_rok_odpisovD").gfield("resetErrors");
                    let typ_odpis = this.findForms("FormOdpD").findFields("df_typ_odpD").gfield("getValue");
                    if (WebClient.testDefOdpVuj(typ_odpis.def_odp) || typ_odpis.def_odp === 0 || (!WebClient.testDefDan(typ_odpis.dan_def))) {
                        if (myVal < 0) {
                            let msg = "Nepřípustná hodnota - aktuální rok odpisování nemůže být záporný.";
                            this.findForms("FormOdpD").findFields("df_rok_odpisovD").gfield("setError", { message: msg });
                            this.dialogs.error(msg);
                            // Set df_rok_odpisov = 0                     
                            return false; // Return VALIDATE_Cancel
                        } // end if
                        let dobaUziti = this.findForms("FormOdpU").findFields("df_doba_uziti").gfield("getValue");
                        if (dobaUziti > 0 && myVal > dobaUziti) {
                            let msg = "Nepřípustná hodnota - aktuální rok odpisování nemůže být vyšší než celková doba používání majetku.";
                            this.findForms("FormOdpD").findFields("df_rok_odpisovD").gfield("setError", { message: msg });
                            this.dialogs.error(msg);
                            // Set df_rok_odpisov = 0
                            return false; // Return VALIDATE_Cancel
                        } // end if
                        // definice recordu
                        this.DetailDto.odp.dan.rok_odpisov = myVal;
                        // změna definice hodnoty ročního odpisu
                        WebClient.redefineRokOdp(bUcetni, this.fillFormOdpisyUcetniOptions());
                        this.findForms("FormOdpU").findFields("df_doba_uziti_ind").gfield("setValue", dobaUziti - myVal);
                        // definice aktivace
                        this.DetailDto.odp.dan.aktivace = 10; // manuální                              
                    }
                    else {
                        let cVstup = parseDecimal(this.DetailDto.odp.dan.c_vstup);
                        let cZust = parseDecimal(this.DetailDto.odp.dan.c_zust);
                        let max_rok = 1;
                        let stop_rok_odp = this.DetailDto.odp.dan.stop_rok_odp;
                        let df_rok_start_odp = this.findForms("FormOdpD").findFields("df_rok_start_odp").gfield("getValue");
                        // definice max. možné hodnoty              
                        if (!cVstup.equals(cZust))
                            max_rok = this.cvEkoRok - df_rok_start_odp - stop_rok_odp + 1;
                        // mapování roku odpisování
                        if (myVal < 1 || myVal > max_rok) {
                            // dialog + chybový text
                            let msg = this.warningValidateOdp('počtu roků odpisování', 1, max_rok);
                            this.findForms("FormOdpD").findFields("df_rok_odpisovD").gfield("setError", { message: msg });
                            // Set df_rok_odpisov = odpis.rok_odpisov
                            return false; // Return VALIDATE_Cancel
                        } // end if
                        // pokud nesedí
                        max_rok = this.cvEkoRok - df_rok_start_odp - stop_rok_odp + 1;
                        if (myVal != max_rok) {
                            let msg = "Nepřípustné hodnoty údajů -  počet roků odpisování, rok počátku odpisu, počet roků přerušení odpisu.";
                            this.findForms("FormOdpD").findFields("df_rok_odpisovD").gfield("setError", { message: msg });
                            this.dialogs.error(msg);
                            // Set df_rok_odpisov = odpis.rok_odpisov
                            return false; // Return VALIDATE_Cancel
                        } // end if
                        // definice recordu a aktivace             
                        this.DetailDto.odp.dan.rok_odpisov = myVal;
                        this.DetailDto.odp.dan.aktivace = 10; // manuální              
                        //  řízení přístupnosti roku zvýšení ceny
                        this.setEnableOdpRokZvysVC();
                        // zobrazení aktuální sazby
                        this.showSazbaKoef(bUcetni);
                    } // end if-else
                    return true; // Return VALIDATE_Ok
                } // end function ( validateRokOdpisov )
                warningValidateOdp(text, min, max) {
                    let errText = "Nepřípustná hodnota " + text + ".\n" +
                        "Přípustný interval je " + min + "-" + max;
                    this.dialogs.error(errText);
                    return errText;
                } // end function
                setEnableOdpRokZvysVC() {
                    // v prvním roce odpisování je nepřístupné
                    var noEdit = this.DetailDto.odp?.dan.rok_odpisov === 0 || this.DetailDto.odp?.dan.rok_odpisov === 1;
                    this.findForms("FormOdpD").findFields("df_rok_zvys_vc").gfield("option", "disabled", noEdit === true);
                } // end function
                showSazbaKoef(bUcetni) {
                    WebClient.showSazbaKoef(bUcetni, this.fillFormOdpisyUcetniOptions());
                } // end function
