                    this.df_c_zustU.Edit = false;
                    this.df_c_zustD.Edit = false;
                    this.df_c_rok_odpU.Edit = false;
                    this.df_c_rok_odpD.Edit = false;
                    this.df_typ_odpU.Edit = false;
                    this.df_typ_odpD.Edit = false;
                    this.df_pro_rm.Edit = false; // Ú
