                        if (this.DetailDto.odp.dan.rok_odpisov === 0 || this.DetailDto.odp.dan.rok_odpisov == 1)
                            this.df_rok_zvys_vc.Edit = false;
                        // pokud nedošlo ke zvýšení ceny, je nepřístupné
