                    let df_doba_uzitiAcc = false; // předpokládáná doba používání
                    // df_doba_uziti_ind  (df_doba_uziti_ind_m - vždy RO)
                    // defodp_uVujZjd nebo defodp_uVujRov  nebo NONE
