                jsCheckDuplIdMaj(value) {
                    if (this.cvDebug) {
                        this.log.trace("CALL --- jsCheckDuplIdMaj() ---");
                        this.log.trace(" WATCH - id_maj = [" + value + "]");
                    } // end if
                    this.call("CheckDuplIdMaj", { idMaj: value })
                        .then((result, content) => {
                        if (result)
                            this.dialogs.error("Evidenční karta se zadaným identifikátorem majetku již existuje!");
                    }); // end then
                } // end function ( jsCheckDuplIdMaj ) 
