            function jsGetSazbaOdp(bUcetni, opts) {
                //this.logSrvCall("GetSazbaOdp");
                //var def = $.Deferred(); // promise
                const karta = opts.content.createServiceContent("Gordic.Maj.WebClient.GMajKarta");
                karta.call("GetSazbaOdp", {
                    odpRec: bUcetni ? opts.DetailDto.odp.ucet : opts.DetailDto.odp.dan
                })
                    .then((retVal, content) => {
                    if (retVal) {
                        if (bUcetni) {
                            // kv�li modelu mus�m vytvo�it celou struktoru DTO
                            let dto = {};
                            dto.odp = {
                                ucet: {
                                    c_sazba_odp: retVal
                                }
                            };
                            opts.getForm("FormOdpU").findFields("df_c_sazba_odpU").gfield("model", "apply", dto, { initialValues: true });
                        }
                        else {
                            // kv�li modelu mus�m vytvo�it celou struktoru DTO
                            let dto = {};
                            dto.odp = {
                                dan: {
                                    c_sazba_odp: retVal
                                }
                            };
                            opts.getForm("FormOdpD").findFields("df_c_sazba_odpD").gfield("model", "apply", dto, { initialValues: true });
                        } // endif-else (bUcetni)
                        //def.resolve();
                    }
                    //else def.reject();                    
                }); // end then (GetSazbaOdp)
            } // end function (jsGetSazbaOdp)
