            // p�epo�et ��stky odpisu v akt. roce
            function redefineRokOdp(bUcetni, opts) {
                // na�ten� def_odp            
                let typOdpis;
                let odpisCOpr;
                if (bUcetni) {
                    typOdpis = opts.getForm("FormOdpU").findFields("df_typ_odpU").gfield("getValue");
                    odpisCOpr = parseDecimal(opts.DetailDto.odp.ucet.c_opr);
                }
                else {
                    typOdpis = opts.getForm("FormOdpD").findFields("df_typ_odpD").gfield("getValue");
                    odpisCOpr = parseDecimal(opts.DetailDto.odp.dan.c_opr);
                } // end if-else
                if (bUcetni && (typOdpis.def_odp === 200 || typOdpis.def_odp === 210 || typOdpis.def_odp === 0)) {
                    if (odpisCOpr.equals(0)) // If odpis.c_opr = 0
                     {
                        // odpis v roce
                        opts.getForm("FormOdpU").findFields("df_pro_r, df_pro_m").gfield("setValue", 0);
                        // record
                        opts.DetailDto.odp.ucet.c_rok_odp = new Decimal(0);
                        opts.getForm("FormOdpU").findFields("df_c_rok_odpU").gfield("model", "apply", opts.DetailDto, { initialValues: true });
                    } // endif (c_opr = 0)
                }
                else {
                    // � v�konov� nebo D def=0 nebo ne ty def.da�ov�
                    if (typOdpis.def_odp === 220 || typOdpis.def_odp === 0 || (!(typOdpis.dan_def === 10 || typOdpis.dan_def === 12))) {
                        // asi net�eba
                        //Set odpis.rok_odpisov = df_rok_odpisov
                        if (odpisCOpr.equals(0)) // If odpis.c_opr = 0
                         {
                            // odpis v roce                        
                            if (bUcetni) {
                                opts.DetailDto.odp.ucet.c_rok_odp = new Decimal(0);
                                opts.getForm("FormOdpU").findFields("df_c_rok_odpU").gfield("model", "apply", opts.DetailDto, { initialValues: true });
                            }
                            else {
                                opts.DetailDto.odp.dan.c_rok_odp = new Decimal(0);
                                opts.getForm("FormOdpD").findFields("df_c_rok_odpD").gfield("model", "apply", opts.DetailDto, { initialValues: true });
                            } // end if-else
                        } // endif (c_opr = 0)
                    }
                    else {
                        // tady jen da�ov� ??
                        if (bUcetni)
                            opts.dialogs.error("redefineRokOdp( ) - neo�ek�van� typ � odpisu"); // PSvoboda - pro jistotu
                        // If odpis.rok_start_odp = EkoInit.Rok and odpis.c_vstup != odpis.c_zust
                        if (opts.DetailDto.odp.dan.rok_start_odp === opts.cvEkoRok && (!parseDecimal(opts.DetailDto.odp.dan.c_vstup).equals(opts.DetailDto.odp.dan.c_zust))) {
                            // odpis v roce
                            let rozdil = parseDecimal(opts.DetailDto.odp.dan.c_vstup).minus(opts.DetailDto.odp.dan.c_zust);
                            opts.DetailDto.odp.dan.c_rok_odp = rozdil;
                            opts.getForm("FormOdpD").findFields("df_c_rok_odpD").gfield("model", "apply", opts.DetailDto, { initialValues: true });
                        }
                        else if (odpisCOpr.equals(0)) { //Else If odpis.c_opr = 0
                            //  pokud je opr�vka 0 - inicializovat
                            // record
                            opts.DetailDto.odp.dan.c_rok_odp = new Decimal(0); // odpis v roce                        
                            opts.DetailDto.odp.dan.rok_zvys_vc = 0; // rok zv��en� VC                        
                            opts.DetailDto.odp.dan.rok_start_odp = opts.cvEkoRok; // rok po��tku odpisu
                            opts.DetailDto.odp.dan.rok_odpisov = 1; // aktu�ln� rok odpisu - zobrazuju o jednu vy���
                            opts.getForm("FormOdpD").findFields("df_c_rok_odpD, df_rok_zvys_vc, df_rok_start_odp, df_rok_odpisovD").gfield("model", "apply", opts.DetailDto, { initialValues: true });
                        }
                        else {
                            // odpis v roce je nulov�
                            opts.DetailDto.odp.dan.c_rok_odp = new Decimal(0);
                            opts.getForm("FormOdpD").findFields("df_c_rok_odpD").gfield("model", "apply", opts.DetailDto, { initialValues: true });
                        } // if-else-else
                    } // end if-else
                } // end if-else (ROV nebo z�kaz)
            } // end function ( redefineRokOdp )
            WebClient.redefineRokOdp = redefineRokOdp;
            // PSvoboda: pouze pro ��etn� ODP
            function validateCZbytekProc(myVal, opts) {
                //this.logFunctionCall("validateCZbytekProc");
                // mo�nost hromadn� zm�ny zbytkov� hodnoty 
                if (opts.argMode === 6) { // ng_modefrmFill
                    if (myVal != 0) {
                        const $df_c_zbytek = opts.getForm("FormOdpU").findFields("df_c_zbytekU");
                        //$df_c_zbytek.gfield("model", "apply", 0, { initialValues: true });
                        $df_c_zbytek.gfield("setValue", 0);
                    }
                }
                else {
                    let df_c_zbytek;
                    let df_c_por;
                    df_c_por = opts.getForm("FormOdpU").findFields("df_c_porU").gfield("getValue");
                    df_c_zbytek = df_c_por.times(myVal).dividedBy(100);
                    opts.getForm("FormOdpU").findFields("df_c_zbytekU").gfield("model", "apply", df_c_zbytek, { initialValues: true });
                    try {
                        validateCZbytek(1, df_c_zbytek, false, opts);
                    }
                    catch {
                        // TODO: do�e�it tuto v�tev, kdy� neprojde validateCZbytek( ) !
                        //df_c_zbytek_proc = 0;
                        // Return VALIDATE_Cancel
                    }
                } // end if-else
                // p�i�azen� do aktu�ln�ho recordu
                opts.DetailDto.odp.ucet.c_zbytek_proc = parseDecimal(myVal);
                // Return VALIDATE_Ok
            } // end function (validateCZbytekProc)
            WebClient.validateCZbytekProc = validateCZbytekProc;
            // v�po�et ��stky s DPH
            function spoctiCDph(castka, sazbaDane) {
                return castka.times(100 + sazbaDane).dividedBy(100);
            } // end function
            WebClient.spoctiCDph = spoctiCDph;
            // toto je kopie funkce v GMajMajPol !!! ale pro JavaScript
            function _setCFlagDph(castka, prizDklCenyVcetneDph, prizDklBezOdpoctuDph, opts) {
                //this.logFunctionCall("_setCFlagDph");
                //this.logWatch("castka", castka);
                //this.logWatch("CenyVcetneDph", prizDklCenyVcetneDph);
                //this.logWatch("BezOdpoctuDph", prizDklBezOdpoctuDph);
                let castkaSDph = castka;
                // z�sk�n� sazby DPH
                var cmb = opts.getForm("FormIDs").findFields("cmb_dan_typ").gfield("getValue");
                if (cmb) {
                    //this.logWatch("cmb_dan_typ.dan_typ", cmb.dan_typ);
                    //this.logWatch("cmb_dan_typ.dan_proc (sazba) ", cmb.dan_proc);
                    var danTyp = cmb.dan_typ;
                    var sazbaDane = cmb.dan_proc;
                    //----------------------------------------------------
                    // pokud je typ_dan = ng_dantypNone, vrac�m to sam�
                    if (danTyp === 0)
                        return castka;
                    // nejsem pl�tce => norm�ln� zad�v�m cenu s DPH
                    if (opts.cvEkoPlatceDph === 0) {
                        if (!prizDklCenyVcetneDph) // c_with_dph  // pokud d�v�m cenu i s DPH, vrac�m to sam�                                        
                            castkaSDph = spoctiCDph(castka, sazbaDane);
                    }
                    else // jsem pl�tce
                     {
                        if (prizDklCenyVcetneDph) // c_with_dph
                            castkaSDph = castka.times(parseDecimal(100).dividedBy(100 + sazbaDane)); //castka * (100 / (100 + sazbaDane));
                        else {
                            // pokud se neuplat�uje odpo�et a je cena zad�v�na bez dph -p�epo��t� se
                            if (prizDklBezOdpoctuDph) // odpocet_dph_no
                                castkaSDph = spoctiCDph(castka, sazbaDane);
                            //else
                            //    return castka; // pokud d�v�m cenu BEZ(!) DPH, vrac�m to sam�
                        } // end if-else                
                    } // end if-else (nepl�tce/pl�tce DPH)
                }
                else {
                    opts.dialogs.error("Nebyla nalezena sazba DPH. ��stky souvisej�c� s dan� nelze spo��tat. \nK�d chyby: 24534032");
                } // endif
                //this.logWatch(" - RETURN - castkaSDph", castkaSDph);
                return castkaSDph;
            } // end function ( _setCFlagDph )
            WebClient._setCFlagDph = _setCFlagDph;
            // TODO: prov��it testem
            function validateCZbytek(rezim, myVal, bUcetni, opts) {
                //this.logFunctionCall("validateCZbytek");
                let formOdpU = opts.getForm("FormOdpU");
                let formOdpD = opts.getForm("FormOdpD");
                let msg = "";
                // mo�nost hromadn� zm�ny zybtkov� hodnoty 
                if (opts.argMode === WebClient.nModeFrmFill) {
                    if (!parseDecimal(myVal).equals(0)) {
                        if (bUcetni) {
                            const $field_proc = formOdpU.findFields("df_c_zbytek_proc");
                            //$field_proc.gfield("model", "apply", 0, { initialValues: true });
                            $field_proc.gfield("setValue", 0);
                        }
                        else
                            opts.DetailDto.odp.dan.c_zbytek_proc = new Decimal(0);
                    }
                }
                else {
                    // TODO: p�epo�et dle p��znak� pr�ce s DPH
                    let df_c_zbytek = parseDecimal(_setCFlagDph(myVal, true, false, opts));
                    let df_c_vstup;
                    if (bUcetni)
                        df_c_vstup = formOdpU.findFields("df_c_vstupU").gfield("getValue");
                    else
                        df_c_vstup = formOdpD.findFields("df_c_vstupD").gfield("getValue");
                    if (df_c_zbytek.greaterThan(df_c_vstup))
                        opts.dialogs.warning("POZOR - zbytkov� hodnota je vy��� ne� vstupn� cena");
                    // vznik karty v d�sledku rozd�len� - cena nesm� b�t vy���
                    if (opts.argMode === WebClient.nModeFrmInsRozM) {
                        if (bUcetni) {
                            opts.dialogs.error("TODO: odpbuff.ucet.c_zbytek");
                            //if (df_c_zbytek > odpbuff.ucet.c_vstup)
                            // Msg._stop( 'Vstupn� cena nesm� p�ev��it cenu rozd�lovan�ho majetku: ' || SalFmtFormatNumber( odpbuff.ucet.c_vstup, '#�##0,00' ) || ',- K�' )
                        }
                        else {
                            opts.dialogs.error("TODO: odpbuff.dan.c_zbytek");
                        } // end if-else
                    } // endif
                    // sou�et opr�vky a zbytkov� hodnoty = vstupn� cena
                    let df_c_opravka;
                    if (bUcetni)
                        df_c_opravka = formOdpU.findFields("df_c_opravkaU").gfield("getValue");
                    else
                        df_c_opravka = formOdpD.findFields("df_c_opravkaD").gfield("getValue");
                    let porov = df_c_vstup.minus(df_c_opravka);
                    if (df_c_zbytek.greaterThan(porov)) {
                        opts.dialogs.error("Nep��pustn� hodnota - p�ekro�ena hodnota vstupn� ceny");
                        return false; // Return VALIDATE_Cancel
                    } // endif
                    // p�i�azen� do aktu�ln�ho recordu
                    if (bUcetni) {
                        opts.DetailDto.odp.ucet.c_zbytek = df_c_zbytek;
                        formOdpU.findFields("df_c_zbytekU").gfield("model", "apply", df_c_zbytek, { initialValues: true });
                    }
                    else {
                        opts.DetailDto.odp.dan.c_zbytek = df_c_zbytek;
                        formOdpD.findFields("df_c_zbytekD").gfield("model", "apply", df_c_zbytek, { initialValues: true });
                    } // end if-else
                    // pokud je vol�n� z pole absolutn� hodnoty zbytku, ma�e se procento
                    if (rezim === 0)
                        formOdpU.findFields("df_c_zbytek_proc").gfield("model", "apply", 0, { initialValues: true });
                    // nastaven� ceny za jednu MJ
                    if (bUcetni) {
                        let df_pc_poc_uzi_mj = formOdpU.findFields("df_pc_poc_uzi_mj").gfield("getValue");
                        if (df_pc_poc_uzi_mj > 0) {
                            let df_c_odp_mj = (df_c_vstup.minus(df_c_zbytek)).dividedBy(df_pc_poc_uzi_mj);
                            formOdpU.findFields("df_c_odp_mj").gfield("model", "apply", df_c_odp_mj, { initialValues: true });
                        } // endif
                    } // endif
                    // TODO: jak nalo�it s da�ov�m?? - otestuj v MAJ01
                } // end if-else
                // Return VALIDATE_Ok
            } // end function (validateCZbytek)
            WebClient.validateCZbytek = validateCZbytek;
