                    //if ((that as any).ekoBookFilter?.rok) $.extend(filters, { rok_den: (that as any).ekoBookFilter.rok });
                    let keysInFilters = "";
                    let i = 0;
                    if (response)
                        response.result.forEach((r) => {
                            if (i++ > 0)
                                keysInFilters += ",";
                            if (jsouZadosti)
                                keysInFilters += r.data.id_ext;
                            else
                                keysInFilters += r.data.ixs_maj;
                        });
                    // vol�n� obecn� metody pro na�ten� dat do pr�vodce
