                    let columnListIgnoreArray = [];
                    // TODO: dodělat podporu ignorovaných sloupců s hvězdičkou, tedy např. "vlastnosti.*")
                    if (columnListIgnore)
                        columnListIgnoreArray = columnListIgnore.split(",");
                    let columnListFull = "";
                    let columnListFullViewPreferArray = [];
                    if (columnListFullViewPrefer)
                        columnListFullViewPreferArray = columnListFullViewPrefer.split(",").filter(c => (columnListCompleteArray.indexOf(c) >= 0 && !existInArray(columnListIgnoreArray, c)));
                    if (columnListFullViewPreferArray && columnListFullViewPreferArray.length > 0) {
                        let columnListFullViewRest = columnListCompleteArray.filter(c => (columnListFullViewPreferArray.indexOf(c) < 0 && !existInArray(columnListIgnoreArray, c))).join(",");
                        columnListFull = columnListFullViewPreferArray.join(",") + (columnListFullViewRest ? "," + columnListFullViewRest : "");
                    }
                    else {
                        columnListFull = columnListCompleteArray.filter(c => !existInArray(columnListIgnoreArray, c)).join(",");
                    }
