                MajGrid.getGridOptions = getGridOptions;
                /**
                 * Pomocná metoda pro zjištění existence prvku v poli, ve kterém mohou být texty s hvězdičkou
                 *
                 * @param {string[]} array prohledávané pole (prvky pole mohou obsahovat text s hvězdičkou)
                 * @param {string} searchString hledaná hodnota
                 * @returns {boolean} true = prvek v poli existuje, false = prvek v poli neexistuje
                 */
                function existInArray(array, searchString) {
                    searchString = searchString.toLowerCase();
                    for (let i = 0; i < array.length; i++) {
                        // přesná shoda
                        if (array[i] === searchString)
                            return true;
                        // hvězdička
                        // TODO: neřeší, pokud za hvězdičkou ještě něco je
                        let p = array[i].indexOf("*");
                        if (p >= 0) {
                            if (p == 0)
                                return true;
                            if ((searchString.length >= p) && (array[i].substring(0, p) === searchString.substring(0, p)))
                                return true;
                        }
                    }
                    return false;
                }
