                    //majpolrec.maj.drh_id = row.drh_id;
                    //majpolrec.maj.mat_cis = row.mat_cis;
                    //majpolrec.maj.dev = row.dev;
                    //majpolrec.maj.zev = row.zev;
                    //options pro zavolání serverové strany majetkové karty 
