                                // TODO: až bude nový typ JQuery.TriggeredEvent u ev, tak odstranit any
                                run: function (ev, ctx) {
                                    return wizardGridActionDetail(ev, ctx, 1, null, params.actions.menuGridDetail, () => { aktivniOperace = true; });
                                },
                                enabled: true
