                                formTabTitle: params.texts.formTabTitle,
                                enableFormFields: false,
                                gridTabTitle: params.texts.gridTabTitle ?? "jres:26850019", //RC 26850019 : Vybrané záznamy
                                menuGridBar: gridActions, //22.1.2025 přidáno - na druhém kroku nebyl detail 
